bool covers(spike::Rect a,spike::Rect b){return !b.empty()&&a.x0<=b.x0&&a.y0<=b.y0&&a.x1>=b.x1&&a.y1>=b.y1;}
struct RoutedCanvas final:Canvas {
 spike::Rect band{};unsigned phases{},duringContact{};bool watch{},contact{},badBudget{};
 explicit RoutedCanvas(ux::Shell& shell):Canvas(shell){}
 spike::Submit submit(spike::Rect r)noexcept override{
  const bool effect=watch&&shell.revealPending()&&covers(r,band);
  if(effect){++phases;if(contact)++duringContact;auto area=std::uint64_t(band.x1-band.x0)*(band.y1-band.y0);badBudget|=area>300000||area>1620ULL*2160/4;}
  return Canvas::submit(r);
 }
 void observe(spike::Rect p){CHECK(!p.empty());band={p.x0+8,p.y0-10,std::min(p.x1-8,p.x0+116),p.y0-2};phases=0;watch=true;badBudget=false;}
 void observe(){observe(shell.semanticVisual().panel);}
};
std::pair<int,int> wordPoint(ux::Shell& shell,const QString& word){auto g=shell.semantics().geometry();CHECK(g&&g->available());auto words=g->data["words"].toArray();for(int n=0;n<words.size();++n){auto selected=semantic::select(g,unsigned(n),unsigned(n),1);if(selected->data["normalized"].toString()!=word)continue;auto q=selected->data["quads"].toArray()[0].toArray();double x=0,y=0;for(int i=0;i<8;i+=2){x+=q[i].toDouble()/4;y+=q[i+1].toDouble()/4;}auto m=g->data["transform"].toArray();return {int(m[0].toDouble()*x+m[2].toDouble()*y+m[4].toDouble()),int(m[1].toDouble()*x+m[3].toDouble()*y+m[5].toDouble())};}throw std::runtime_error("authored-word-missing");}
QByteArray regionHash(const std::vector<std::uint32_t>& pixels,spike::Rect r){QByteArray bytes;for(int y=r.y0;y<r.y1;++y)bytes.append(reinterpret_cast<const char*>(pixels.data()+std::size_t(y)*1632+r.x0),(r.x1-r.x0)*4);return underlay::digest(bytes);}
void capture(const Path& path,const RoutedCanvas& canvas){QImage image(reinterpret_cast<const uchar*>(canvas.pixels.data()),1620,2160,1632*4,QImage::Format_RGB32);CHECK(image.save(QString::fromStdString(path.string())));}
void settled(ux::Shell& shell,RoutedCanvas& canvas){until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return shell.styledInk()&&!shell.styledInk()->status().busy&&shell.unsaved()==0;});}
void clearEffect(ux::Shell& shell,RoutedCanvas& canvas){until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return !shell.revealPending();});CHECK(canvas.phases<=3&&!canvas.badBudget);}
void dismiss(ux::Shell& shell,RoutedCanvas& canvas){CHECK(shell.semantics().view()!=semantic::View::None);CHECK(shell.finger(1450,1800,false));canvas.changes();clearEffect(shell,canvas);CHECK(shell.semantics().view()==semantic::View::None);canvas.watch=false;}
void definition(ux::Shell& shell,RoutedCanvas& canvas,bool expectedEffect){auto original=canvas.pixels;canvas.watch=false;auto at=wordPoint(shell,"orchard");CHECK(selectForActions(shell,at.first,at.second));CHECK(shell.semantics().view()==semantic::View::Menu&&uitest::tap(shell,shell.semanticVisual().targets.rect(ib::reader::SelDefine)));canvas.changes();until([&]{shell.tick();CHECK(!shell.failed());if(shell.semantics().view()==semantic::View::Definition){canvas.observe();canvas.changes();return true;}canvas.changes();return false;});CHECK(shell.semantics().definition()["provider"]=="princeton-wordnet-3.0"&&shell.semantics().definition()["status"]=="FOUND");auto selected=semantic::bounds(shell.semantics().selection()->data);selected.x0+=2;selected.y0+=2;selected.x1-=2;selected.y1-=2;CHECK(regionHash(original,selected)==regionHash(canvas.pixels,selected));CHECK(shell.revealPending()==expectedEffect);if(expectedEffect)CHECK(canvas.phases==1);else CHECK(canvas.phases==0);}
spike::Rect insetContent(spike::Rect p){return {p.x0+16,p.y0+24,p.x1-16,p.y1-16};}
void tools(ux::Shell& shell,RoutedCanvas& canvas,bool effect){CHECK(shell.action(ux::Action::Show));canvas.changes();canvas.observe(insetContent(ux::ToolsView::panel()));CHECK(uitest::openTools(shell));shell.tick();canvas.changes();CHECK(shell.revealPending()==effect);CHECK(canvas.phases==(effect?1u:0u));}
void closeTools(ux::Shell& shell,RoutedCanvas& canvas){auto r=uitest::toolsClose(shell);CHECK(shell.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2,false));shell.tick();canvas.changes();clearEffect(shell,canvas);CHECK(shell.action(ux::Action::Hide));canvas.changes();settled(shell,canvas);canvas.watch=false;}
void viewSettings(ux::Shell& shell,RoutedCanvas& canvas,bool effect){CHECK(shell.action(ux::Action::Show));canvas.changes();canvas.observe(insetContent(ux::DocumentControls::Panel));CHECK(uitest::openSettings(shell));shell.tick();canvas.changes();CHECK(shell.revealPending()==effect);CHECK(canvas.phases==(effect?1u:0u));}
void closeView(ux::Shell& shell,RoutedCanvas& canvas){CHECK(uitest::setting(shell,ib::sheets::Cancel));shell.tick();canvas.changes();clearEffect(shell,canvas);CHECK(shell.action(ux::Action::Hide));canvas.changes();canvas.watch=false;}
